//! Ruby: the `ffi`-gem bindings (`target/codegen/azul.rb`, generated by
//! `doc/src/codegen/v2/lang_ruby`).
//!
//! The generated code uses the raw layer `Azul::Native` (aliased `N`): the
//! attached C functions under their snake_case names
//! (`N.az_css_property_text_color(..)`, `N.az_layout_width_px(..)`), the enum
//! constant modules (`N::AzLayoutDisplay::Flex`), and the `FFI::Struct`
//! classes. Ruby's FFI structs are filled with statements, and a nested
//! struct must be copied into its field's bytes, so the generated
//! `AzulCodegen.struct` / `.union` / `.vec` helpers do that and return the
//! value (a union is `{ tag, payload: { Variant: { payload } } }` in
//! `azul.rb`). Strings go through `Azul._az_string`.

use alloc::{
    format,
    string::{String, ToString},
    vec,
    vec::Vec,
};

use crate::codegen::{
    doc::{render, Doc},
    ir::{snake_to_lower_camel, EnumShape, Item, Module, Prim},
    lang::{
        escape_quoted, item_comments, item_doc, simple_snake, unicode_braced, variant_ctor_method,
        ExprSyntax,
    },
    lower_types::{is_c_like_enum, union_tag},
    CodegenBackend, GeneratedFile,
};

/// The Ruby printer.
#[derive(Debug, Copy, Clone, Default)]
pub struct Ruby;

/// `N.az_css_property_text_color` for `CssProperty::text_color`.
fn native_fn(class: &str, c_method: &str) -> String {
    format!("N.{}", simple_snake(&format!("Az{class}_{c_method}")))
}

impl ExprSyntax for Ruby {
    fn int(&self, value: i128, _ty: Prim) -> String {
        value.to_string()
    }

    fn float(&self, text: &str, _ty: Prim) -> String {
        match text {
            "nan" => "Float::NAN".to_string(),
            "inf" => "Float::INFINITY".to_string(),
            "-inf" => "-Float::INFINITY".to_string(),
            _ => text.to_string(),
        }
    }

    fn boolean(&self, b: bool) -> String {
        b.to_string()
    }

    fn string(&self, s: &str) -> Doc {
        Doc::text(format!(
            "Azul._az_string(\"{}\")",
            escape_quoted(s, &['#'], &unicode_braced)
        ))
    }

    fn call(&self, class: &str, method: &str, args: Vec<Doc>, broken: bool) -> Doc {
        Doc::call(native_fn(class, &snake_to_lower_camel(method)), args, broken)
    }

    fn variant(&self, ty: &str, shape: EnumShape, variant: &str, args: Vec<Doc>, broken: bool) -> Doc {
        match shape {
            EnumShape::CLike => Doc::text(format!("N::Az{ty}::{variant}")),
            EnumShape::Tagged => Doc::call(native_fn(ty, &variant_ctor_method(variant)), args, broken),
            EnumShape::TaggedShadowed | EnumShape::Generic { .. } => {
                let tag = union_tag(ty, variant).unwrap_or(0);
                let mut all = vec![
                    Doc::text(format!("N::Az{ty}")),
                    Doc::text(format!(":{variant}")),
                    Doc::text(tag.to_string()),
                ];
                all.extend(args);
                Doc::call("AzulCodegen.union", all, broken)
            }
        }
    }

    fn strukt(&self, ty: &str, fields: Vec<(String, Doc)>, broken: bool) -> Doc {
        let mut all = vec![Doc::text(format!("N::Az{ty}"))];
        all.extend(
            fields
                .into_iter()
                .map(|(k, v)| Doc::cat(vec![Doc::text(format!("{k}: ")), v])),
        );
        Doc::call("AzulCodegen.struct", all, broken)
    }

    fn vec(&self, ty: &str, elem: &str, items: Vec<Doc>, broken: bool) -> Doc {
        if items.is_empty() {
            return Doc::text(format!("{}()", native_fn(ty, "create")));
        }
        let klass = if is_c_like_enum(elem) {
            "nil".to_string()
        } else {
            format!("N::Az{elem}")
        };
        let mut all = vec![
            Doc::text(format!(":{}", simple_snake(&format!("Az{ty}_copyFromPtr")))),
            Doc::text(klass),
        ];
        all.extend(items);
        Doc::call("AzulCodegen.vec", all, broken)
    }

    fn unsupported(&self, what: &str) -> Doc {
        Doc::text(format!("raise({:?})", format!("not expressible: {what}")))
    }
}

const HELPERS: &str = r"module AzulCodegen
  N = Azul::Native

  # An FFI struct from field values; a nested struct is copied into its field.
  def self.struct(klass, **fields)
    s = klass.new
    fields.each do |name, value|
      if value.is_a?(FFI::Struct)
        s.pointer.put_bytes(klass.offset_of(name), value.pointer.read_bytes(value.size))
      else
        s[name] = value
      end
    end
    s
  end

  # A tagged union: the tag plus the variant's payload (copied in).
  def self.union(klass, variant, tag, payload = nil)
    u = klass.new
    u[:tag] = tag
    unless payload.nil?
      arm = u[:payload][variant]
      if payload.is_a?(FFI::Struct)
        arm.pointer.put_bytes(arm.class.offset_of(:payload), payload.pointer.read_bytes(payload.size))
      else
        arm[:payload] = payload
      end
    end
    u
  end

  # Copies the items into native memory; the C API clones them into the Vec.
  def self.vec(copy_fn, klass, *items)
    size = klass.nil? ? 4 : klass.size
    buf = FFI::MemoryPointer.new(:uint8, size * items.size)
    items.each_with_index do |item, i|
      if klass.nil?
        buf.put_int32(i * size, item)
      else
        buf.put_bytes(i * size, item.pointer.read_bytes(size))
      end
    end
    N.public_send(copy_fn, buf, items.size)
  end
end
";

fn item_fn(item: &Item) -> String {
    let mut out = String::new();
    for line in &item_comments(&Ruby, item) {
        out.push_str(&format!("  # {line}\n"));
    }
    let name = item.name.snake();
    match item_doc(&Ruby, item) {
        Ok(doc) => out.push_str(&format!(
            "  def self.{name}\n    {}\n  end\n",
            render(&doc, "  ", 2)
        )),
        Err(reason) => out.push_str(&format!(
            "  # not expressible with the Ruby bindings: {reason}\n  def self.{name}\n    nil\n  \
             end\n"
        )),
    }
    out
}

impl CodegenBackend for Ruby {
    fn lang(&self) -> &'static str {
        "ruby"
    }

    fn aliases(&self) -> &'static [&'static str] {
        &["rb"]
    }

    fn display_name(&self) -> &'static str {
        "Ruby"
    }

    fn extension(&self) -> &'static str {
        "rb"
    }

    fn emit_module(&self, m: &Module) -> String {
        let mut out = String::from(
            "# Generated by azul-css codegen (Ruby). Do not edit by hand.\nrequire 'azul'\n\n",
        );
        out.push_str(HELPERS);
        out.push_str("\nmodule AzulStyles\n  N = Azul::Native\n");
        for item in &m.items {
            out.push('\n');
            out.push_str(&item_fn(item));
        }
        out.push_str("end\n");
        out
    }

    fn emit_project_files(&self, m: &Module) -> Vec<GeneratedFile> {
        let mut main = String::from(
            "# Copy target/codegen/azul.rb and libazul next to this file, then: ruby -I. \
             main.rb\nrequire_relative 'styles'\n",
        );
        for item in &m.items {
            let name = item.name.snake();
            main.push_str(&format!(
                "\n{name} = AzulStyles.{name}\nputs \"{name}: #{{{name}[:len]}} properties\"\n"
            ));
        }
        vec![
            GeneratedFile {
                path: "Gemfile".to_string(),
                contents: "source 'https://rubygems.org'\n\ngem 'ffi'\n".to_string(),
            },
            GeneratedFile {
                path: "styles.rb".to_string(),
                contents: self.emit_module(m),
            },
            GeneratedFile {
                path: "main.rb".to_string(),
                contents: main,
            },
        ]
    }
}
